const input = $input.first().json || {};
const allowedBaseUrl = 'http://mcp_server:8000';
const baseUrl = String(input.URL_MCP || '').trim().replace(/\/+$/, '');
const request = input.catalog_request && typeof input.catalog_request === 'object'
  ? input.catalog_request
  : { scope: 'all', term: '', intent_type: 'catalog_browse' };
const configValid = baseUrl === allowedBaseUrl;

return [{
  json: {
    catalog_request: request,
    catalog_context_key: String(input.catalog_context_key || `catalog:${input.source_message_id || 'unknown'}`),
    source_message_id: String(input.source_message_id || ''),
    channel_family: String(input.channel_family || 'generic'),
    supports_meta_interactive: Boolean(input.supports_meta_interactive),
    phone_number: String(input.phone_number || ''),
    catalog_url: configValid ? `${allowedBaseUrl}/api/products/catalog-carousel` : '',
    catalog_lookup_config_valid: configValid,
  },
}];

const context = $('Prepare Catalog Request').first().json || {};
const responseItems = $input.all().map((item) => item.json || {});

function normalize(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function slug(value, max = 40) {
  return normalize(value).replace(/\s+/g, '_').slice(0, max) || 'catalog';
}

function short(value, max) {
  const text = String(value || '').trim();
  return text.length > max ? `${text.slice(0, max - 3)}...` : text;
}

function absoluteHttps(value) {
  const text = String(value || '');
  if (!text || /[\u0000-\u0020\u007f]/.test(text) || text.includes('\\') || /%(?![0-9a-f]{2})/i.test(text)) return '';

  const match = /^https:\/\/([^/?#]+)(?:[/?#][^\s\\]*)?$/i.exec(text);
  if (!match) return '';

  const authority = match[1];
  if (!authority || authority.includes('@') || authority.startsWith('[')) return '';

  const firstColon = authority.indexOf(':');
  const lastColon = authority.lastIndexOf(':');
  if (firstColon !== lastColon) return '';

  const host = firstColon === -1 ? authority : authority.slice(0, firstColon);
  const port = firstColon === -1 ? '' : authority.slice(firstColon + 1);
  if (!host || host.length > 253 || (port && (!/^\d{1,5}$/.test(port) || Number(port) < 1 || Number(port) > 65535))) return '';

  const canonicalHost = host.endsWith('.') ? host.slice(0, -1) : host;
  const labels = canonicalHost.split('.');
  if (!canonicalHost || labels.some((label) => !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(label))) return '';

  if (/^\d+(?:\.\d+){3}$/.test(canonicalHost)
    && labels.some((label) => !/^\d{1,3}$/.test(label) || Number(label) > 255)) return '';

  return text;
}

function extractRows(value) {
  if (Array.isArray(value)) return value;
  if (!value || typeof value !== 'object') return [];
  for (const key of ['results', 'products', 'items']) {
    if (Array.isArray(value[key])) return value[key];
  }
  if (value.data !== undefined) {
    const nested = extractRows(value.data);
    if (nested.length || Array.isArray(value.data)) return nested;
  }
  if (value.id !== undefined || value.product_id !== undefined) return [value];
  return [];
}

let statusCode = null;
let lookupError = !context.catalog_lookup_config_valid;
const rawRows = [];
for (const response of responseItems) {
  const code = Number(response.statusCode || response.status || 0);
  if (code) statusCode = code;
  if (code >= 400 || response.error) lookupError = true;
  const payload = Object.prototype.hasOwnProperty.call(response, 'body') ? response.body : response;
  rawRows.push(...extractRows(payload));
}

const request = context.catalog_request || {};
const scope = String(request.scope || 'all');
const requestedTerm = normalize(request.term || '');
const seen = new Set();
const products = [];
for (const row of rawRows) {
  const id = String(row.id ?? row.product_id ?? row.sku ?? '').trim();
  const name = String(row.name ?? row.product_name ?? row.model ?? '').trim();
  if (!id || !name || seen.has(id)) continue;

  if (requestedTerm && scope !== 'all') {
    const searchable = scope === 'segment'
      ? normalize([row.segment, row.category, row.type, row.body_type].filter(Boolean).join(' '))
      : normalize([row.name, row.model, row.version, row.variant, row.category].filter(Boolean).join(' '));
    const singularTerm = requestedTerm.replace(/s$/, '');
    if (!searchable.includes(requestedTerm) && !(singularTerm && searchable.includes(singularTerm))) continue;
  }

  seen.add(id);
  const descriptiveValue = [row.version, row.variant, row.segment, row.category]
    .find((value) => value !== null && value !== undefined && String(value).trim() !== '' && normalize(value) !== 'all');
  const subtitle = [descriptiveValue, row.price_from || row.price]
    .filter((value) => value !== null && value !== undefined && String(value).trim() !== '')
    .map(String)
    .join(' | ');
  products.push({
    id,
    name,
    subtitle: short(subtitle, 120),
    image_url: absoluteHttps(row.image_url || row.image1 || row.image || ''),
  });
}

const imageProducts = products.filter((product) => product.image_url).slice(0, 10);
const textProducts = products.slice(0, 10);
const supportsMeta = Boolean(context.supports_meta_interactive)
  && /whatsapp|waba/i.test(String(context.channel_family || ''));
const phone = String(context.phone_number || '').replace(/[^0-9]/g, '');
const canCarousel = supportsMeta && phone.length >= 8 && imageProducts.length >= 2;
const catalogKey = String(context.catalog_context_key || `catalog:${context.source_message_id || 'unknown'}`);
const callbackContext = slug(catalogKey, 40);

function result(fields) {
  return {
    json: {
      catalog_context_key: catalogKey,
      source_message_id: String(context.source_message_id || ''),
      catalog_result_count: products.length,
      catalog_lookup_status_code: statusCode,
      catalog_callback_consumption_supported: false,
      catalog_callback_status: 'encoded_with_title_fallback_unconsumed',
      delivery_attachments: [],
      private_note_content: '',
      ...fields,
    },
  };
}

function textFallback(reason) {
  if (reason === 'lookup_failed') {
    return 'No pude consultar el catálogo en este momento. Intenta nuevamente en unos minutos.';
  }
  if (!textProducts.length) {
    return 'No encontré vehículos disponibles para esa búsqueda. Puedo ayudarte con otra categoría o modelo.';
  }
  if (textProducts.length === 1) {
    const product = textProducts[0];
    return `Encontré una opción disponible: ${product.name}${product.subtitle ? ` (${product.subtitle})` : ''}. Dime si quieres conocer sus detalles o agendar una visita.`;
  }
  const lines = ['Estas son las opciones disponibles:'];
  for (const product of textProducts) {
    lines.push(`- ${product.name}${product.subtitle ? `: ${product.subtitle}` : ''}`);
  }
  lines.push('Dime cuál quieres conocer mejor.');
  return lines.join('\n');
}

if (lookupError && rawRows.length === 0) {
  return [result({ delivery_route: 'chat_text', interactive_type: 'none', delivery_text: textFallback('lookup_failed'), meta_request_body: null, catalog_delivery_reason: context.catalog_lookup_config_valid ? 'lookup_failed' : 'invalid_catalog_host' })];
}

if (!canCarousel) {
  const reason = !textProducts.length
    ? 'no_results'
    : (textProducts.length === 1 ? 'single_product' : (!supportsMeta || phone.length < 8 ? 'unsupported_channel' : 'insufficient_images'));
  return [result({ delivery_route: 'chat_text', interactive_type: 'none', delivery_text: textFallback(reason), meta_request_body: null, catalog_delivery_reason: reason })];
}

const cards = imageProducts.map((product, index) => {
  const productKey = slug(product.id, 40);
  const infoTitle = short(`Info ${product.name}`, 20);
  const visitTitle = short(`Visitar ${product.name}`, 20);
  return {
    card_index: index,
    type: 'cta_url',
    header: { type: 'image', image: { link: product.image_url } },
    body: { text: short(`${product.name}${product.subtitle ? `\n${product.subtitle}` : ''}`, 160) },
    action: {
      buttons: [
        { type: 'quick_reply', quick_reply: { id: `catalog__${callbackContext}__product_${productKey}__more_info`, title: infoTitle } },
        { type: 'quick_reply', quick_reply: { id: `catalog__${callbackContext}__product_${productKey}__test_drive`, title: visitTitle } },
      ],
    },
  };
});

const intro = scope === 'segment' && request.term
  ? `Estas son las opciones disponibles en ${String(request.term).trim()}.`
  : (scope === 'model_versions' && request.term
    ? `Estas son las versiones disponibles de ${String(request.term).trim()}.`
    : 'Te comparto los vehículos disponibles.');

return [result({
  delivery_route: 'meta_interactive',
  interactive_type: 'carousel',
  delivery_text: intro,
  meta_request_body: {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: phone,
    type: 'interactive',
    interactive: {
      type: 'carousel',
      body: { text: short(intro, 1024) },
      action: { cards },
    },
  },
  private_note_content: `Catálogo determinístico preparado con ${cards.length} vehículos.`,
  catalog_delivery_reason: 'carousel',
})];
